        return IntegrationResult(
            provider="stripe",
            action="sync",
            status="error",
            message=f"Stripe API failure: {exc}",
            details={"exceptions": ["stripe_api_failure"]},
        )

    processed: list[str] = []
    new_payouts = 0
    new_recons = 0
    last_breakdown = None
    for obj in targets:
        pid = str(obj.get("id") or "")
